// Normaliza o evento MESSAGES_UPSERT da Evolution v2.
const corpo = $input.first().json.body ?? $input.first().json;
const evento = String(corpo.event ?? '').toLowerCase().replace('_', '.');
const d = corpo.data ?? {};
const key = d.key ?? {};
const m = d.message ?? {};

const ehCliente = evento === 'messages.upsert'
  && key.fromMe !== true
  && String(key.remoteJid ?? '').endsWith('@s.whatsapp.net');
if (!ehCliente) return [];

// Resposta de botão ou lista (API oficial ou botões da Evolution) chega como o id da opção: "1", "2", "0".
const idDoFluxo = (() => {
  try { return JSON.parse(m.interactiveResponseMessage?.nativeFlowResponseMessage?.paramsJson ?? 'null')?.id; }
  catch { return undefined; }
})();
const texto = m.buttonsResponseMessage?.selectedButtonId
  ?? m.listResponseMessage?.singleSelectReply?.selectedRowId
  ?? m.templateButtonReplyMessage?.selectedId
  ?? idDoFluxo
  ?? m.conversation
  ?? m.extendedTextMessage?.text
  ?? m.imageMessage?.caption
  ?? m.documentMessage?.caption
  ?? m.documentWithCaptionMessage?.message?.documentMessage?.caption
  ?? '';
const temMidia = !!(m.imageMessage || m.documentMessage || m.documentWithCaptionMessage);
if (!texto && !temMidia) return []; // áudio, figurinha, reação etc.

return [{ json: {
  remoteJid: key.remoteJid,
  numero: String(key.remoteJid).split('@')[0],
  messageId: key.id,
  nome: d.pushName ?? null,
  texto,
  temMidia,
} }];

